), matched as (
  select v.id, jsonb_strip_nulls(jsonb_build_object(
    'tenBest', s.ten_best, 'editorsChoice', s.editors_choice
  )) as awards
  from award_source s
  join public.makes mk on lower(mk.name) = lower(s.make_name)
  join public.models mo on mo.make_id = mk.id and lower(mo.name) = lower(s.model_name)
  join public.model_year_vehicles v on v.model_id = mo.id and v.model_year = s.model_year
)
update public.page_audit_entries a
   set awards = m.awards
  from matched m
 where a.model_year_vehicle_id = m.id
   and a.awards = '{}'::jsonb;


